from django.contrib.auth.mixins import LoginRequiredMixin
from django.urls import reverse_lazy
from django.views.generic import CreateView, DeleteView, DetailView, ListView
from .models import Post

class PostListView(ListView):
    model = Post
    paginate_by = 20                              # template: blog/post_list.html
    def get_queryset(self):
        return Post.objects.published().select_related("author")

class PostDetailView(DetailView):
    model = Post                                  # URL: <slug:slug>/ -> lookup by slug
class PostCreateView(LoginRequiredMixin, CreateView):
    model = Post
    fields = ["title", "slug", "body"]            # template: blog/post_form.html
    def form_valid(self, form):
        form.instance.author = self.request.user.author
        return super().form_valid(form)
class PostDeleteView(LoginRequiredMixin, DeleteView):
    model = Post
    success_url = reverse_lazy("blog:list")
    def get_queryset(self):                       # only your own posts
        return Post.objects.filter(author__user=self.request.user)

from django.db import models
from django.db.models import Q
from django.urls import reverse
from django.utils import timezone
class PostQuerySet(models.QuerySet):
    def published(self):
        return self.filter(status="pub", published_at__lte=timezone.now())
    def by(self, author):
        return self.filter(author=author)
class Post(models.Model):
    title = models.CharField(max_length=200)
    slug = models.SlugField()
    author = models.ForeignKey("Author", on_delete=models.CASCADE, related_name="posts")
    status = models.CharField(max_length=5, default="draft")
    views = models.IntegerField(default=0)
    published_at = models.DateTimeField(null=True, blank=True)
    objects = PostQuerySet.as_manager()
    class Meta:
        ordering = ["-published_at"]
        indexes = [models.Index(fields=["status", "-published_at"])]
        constraints = [models.UniqueConstraint(fields=["author", "slug"], name="unique_author_slug"),
                       models.CheckConstraint(condition=Q(views__gte=0), name="views_gte_0")]
    def get_absolute_url(self):
        return reverse("blog:detail", kwargs={"slug": self.slug})
