from django.core.cache import cache
from django.db.models import Count
from django.shortcuts import render
from django.views.decorators.cache import cache_page
from .models import Tag

def popular_tags():
    return cache.get_or_set(
        "popular-tags:v1",
        lambda: list(Tag.objects.annotate(n=Count("posts")).order_by("-n").values("name", "n")[:10]),
        timeout=600)

@cache_page(60 * 5)                     # whole response, keyed by URL
def archive(request, year):
    return render(request, "blog/archive.html", {"year": year, "tags": popular_tags()})

def on_post_saved():                    # call when posts change
    cache.delete("popular-tags:v1")
